import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import { FaBook, FaChartLine, FaTasks } from "react-icons/fa";
import AlertBox from "./AlertBox";

function StudentDashboard() {
  const userId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [progress, setProgress] = useState({});
  const [alert, setAlert] = useState(null);

  const fetchCourses = useCallback(async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = res.data.courses || [];

      const enrollRes = await axios.get(
        `http://127.0.0.1:8000/enrollments/${userId}`
      );
      const enrolledIds = enrollRes.data.map((e) => e.course_id);
      const myCourses = allCourses.filter((c) => enrolledIds.includes(c.id));
      setCourses(myCourses);

      const progressRes = await axios.get(
        `http://127.0.0.1:8000/progress/${userId}`
      );
      const progressMap = {};
      progressRes.data.forEach((item) => {
        progressMap[item.course_id] = {
          completed_topics: item.completed_topics,
          total_topics: item.total_topics,
          status: item.status
        };
      });
      setProgress(progressMap);
    } catch (err) {
      console.error(err);
    }
  }, [userId]);

  useEffect(() => {
    fetchCourses();
  }, [fetchCourses]);

  const handleProgress = async (courseId, value) => {
    try {
      const response = await axios.post(
        "http://127.0.0.1:8000/update-progress",
        {
          user_id: parseInt(userId),
          course_id: courseId,
          completed_topics: parseInt(value)
        }
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      fetchCourses();
    } catch (err) {
      setAlert({
        message: "Failed to update progress",
        type: "error"
      });
    }
  };

  const completedCount = Object.values(progress).filter(
    (p) => p.status === "Completed"
  ).length;

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gap: "20px",
          marginBottom: "25px"
        }}
      >
        <div style={cardStyle("#ede7f6")}>
          <h3>Enrolled Courses</h3>
          <p style={numberStyle}>{courses.length}</p>
        </div>
        <div style={cardStyle("#e3f2fd")}>
          <h3>Completed</h3>
          <p style={numberStyle}>{completedCount}</p>
        </div>
        <div style={cardStyle("#f3e5f5")}>
          <h3>Learning</h3>
          <p style={numberStyle}><FaTasks /></p>
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(270px, 1fr))",
          gap: "20px"
        }}
      >
        {courses.map((course) => {
          const courseProgress = progress[course.id] || {
            completed_topics: 0,
            total_topics: 10,
            status: "In Progress"
          };

          const percentage = Math.round(
            (courseProgress.completed_topics / courseProgress.total_topics) * 100
          );

          return (
            <div key={course.id} style={courseBox}>
              <div style={{ fontSize: "26px", color: "#7b1fa2" }}>
                <FaBook />
              </div>

              <h3>{course.title}</h3>
              <p>{course.description}</p>
              <p><strong>Subject Code:</strong> {course.subject_code}</p>

              <div style={progressOuter}>
                <div style={{ ...progressInner, width: `${percentage}%` }}></div>
              </div>

              <p>Progress: {percentage}%</p>
              <p>Status: <strong>{courseProgress.status}</strong></p>

              <input
                type="number"
                min="0"
                max={courseProgress.total_topics}
                placeholder={`Completed topics (0-${courseProgress.total_topics})`}
                id={`progress-${course.id}`}
                style={inputStyle}
              />

              <button
                onClick={() => {
                  const value = document.getElementById(`progress-${course.id}`).value;
                  handleProgress(course.id, value || 0);
                }}
                style={primaryBtn}
              >
                <FaChartLine /> Update Progress
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

const cardStyle = (bg) => ({
  background: bg,
  borderRadius: "16px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.06)"
});

const numberStyle = {
  fontSize: "28px",
  fontWeight: "bold",
  color: "#4a148c"
};

const courseBox = {
  background: "#fff",
  borderRadius: "16px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
};

const progressOuter = {
  height: "10px",
  background: "#eee",
  borderRadius: "10px",
  margin: "10px 0"
};

const progressInner = {
  height: "100%",
  background: "#7b1fa2",
  borderRadius: "10px"
};

const inputStyle = {
  width: "100%",
  padding: "8px",
  borderRadius: "8px",
  border: "1px solid #ccc",
  marginTop: "8px"
};

const primaryBtn = {
  marginTop: "10px",
  width: "100%",
  background: "#7b1fa2",
  color: "#fff",
  border: "none",
  padding: "10px",
  borderRadius: "8px",
  cursor: "pointer"
};

export default StudentDashboard;
